def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def rewrite(value,before,after):
    if isinstance(value,str):
        return value.replace(before,after)
    if isinstance(value,list):
        return [rewrite(v,before,after) for v in value]
    if isinstance(value,dict):
        return {k.replace(before,after):rewrite(v,before,after) for k,v in value.items()}
    return value

def derive(parent,mode):
    selected=SPEC['modes'][mode]
    result=copy.deepcopy(parent)
    result.update(copy.deepcopy(SPEC['common']))
    result['independent_branch']=copy.deepcopy(selected['independent_branch'])
    result['numeric_parameter_scope']=copy.deepcopy(selected['numeric_parameter_scope'])
    # Rebuild the complete original two steps, retaining every other field.
    result['steps']=rewrite(parent['steps'],'run10-detached-closure-values-first',selected['output_prefix'])
    science,pure=result['steps']
    science.update(id=selected['science_id'],script=selected['science_script'],scope=selected['science_scope'])
    pure.update(id=selected['pure_id'],script=selected['pure_script'],scope=selected['pure_scope'])
    args=science['args']
    index=args.index('--angles')
    if args[index+1]!='2048':
        raise ValueError('The declared actual N2048 parent parameter changed')
    args[index+1]='4096'
    if mode=='independent':
        args.extend(['--pending-parallel-envelope-run','45972294636/1',
            '--pending-parallel-envelope-source','45972294636/1=c3dc77f40445eaf30ab743311dd97ea7d62a41be80db504fc778eccffa30e5d1'])
    else:
        rebuilt=[];i=0
        while i<len(args):
            if args[i]=='--independent-envelope-branch':
                i+=1;continue
            if args[i] in ('--pending-parallel-envelope-run','--pending-parallel-envelope-source'):
                i+=2;continue
            rebuilt.append(args[i]);i+=1
        rebuilt.extend(['--material-envelope-parent-report','{work}/run10-detached-closure-values-first/report.json'])
        if mode=='final':
            rebuilt.extend(['--material-envelope-seed-report','{work}/run10-detached-closure-values-first/report.json',
                '--material-envelope-seed-checkpoint','{work}/run10-detached-closure-values-first/final.npz'])
        science['args']=rebuilt
    if science['args']!=selected['science_args'] or pure['args']!=selected['pure_args']:
        raise ValueError('Keep every complete original numerical word and the explicit source/mode changes')
    next(iter(science['summary'].values())).update(SPEC['science_selectors'])
    next(iter(pure['summary'].values())).update(SPEC['pure_selectors'])
    for old,new in zip(parent['steps'],result['steps']):
        before=next(iter(old['summary'].values()));after=next(iter(new['summary'].values()))
        if any(after.get(k)!=v for k,v in before.items()):
            raise ValueError('No original summary selector may be removed or changed')
    return {key:result[key] for key in SPEC['top_key_order']}

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo',type=Path,required=True)
    p.add_argument('--outdir',type=Path,required=True)
    a=p.parse_args()
    repo=a.repo.resolve();outdir=a.outdir.resolve()
    if outdir==repo or repo in outdir.parents:
        raise ValueError('Reproduce the parameter plans in separate scratch')
    source=repo/SPEC['parent']['path'];raw=source.read_bytes()
    if len(raw)!=SPEC['parent']['bytes'] or sha(raw)!=SPEC['parent']['sha256']:
        raise ValueError('The entire actual run10 parent ready changed')
    parent=json.loads(raw);outputs={}
    for mode,value in SPEC['modes'].items():
        plan=derive(parent,mode)
        encoded=(json.dumps(plan,ensure_ascii=False,separators=(',',':'))+'\n').encode('utf-8')
        expected=value['output']
        if len(encoded)>=100000 or len(encoded)!=expected['bytes'] or sha(encoded)!=expected['sha256']:
            raise ValueError('The entire output parameter plan differs: '+mode)
        outdir.mkdir(parents=True,exist_ok=True)
        path=outdir/expected['name']
        if path.exists() and path.read_bytes()!=encoded:
            raise ValueError('Do not overwrite a different complete plan')
        path.write_bytes(encoded)
        outputs[mode]=dict(bytes=len(encoded),sha256=sha(encoded),path=str(path))
    if source.read_bytes()!=raw:
        raise ValueError('The original whole parent parameters changed during reproduction')
    print(json.dumps(dict(complete=True,source_only=True,executed_science=False,outputs=outputs),sort_keys=True))

if __name__=='__main__':
    main()
